import {useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {ArrowDownUp,ArrowLeft,ArrowRight,ArrowUpRight,Bookmark,Check,CheckCheck,ChevronDown,ChevronRight,CircleHelp,ClipboardList,Clock,Flower2,LayoutGrid,Leaf,LogOut,MapPin,Menu,Package,Plus,Search,Settings,ShieldCheck,SlidersHorizontal,Sprout,Tractor,Users,WifiOff,X,Wheat,Apple,Carrot,Bean,CheckCircle2,Phone,Download,RefreshCw,ShoppingCart} from 'lucide-react';
